css:
.loader { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size) * .07); width: var(--loader-size); height: calc(var(--loader-size) * .45); }
.loader span { width: calc(var(--loader-size) * .11); height: calc(var(--loader-size) * .11); border-radius: 9999px; background: var(--loader-color); animation: twWave calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .1); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes twWave { 0%, 100% { transform: translateY(55%); opacity: .4; } 50% { transform: translateY(-55%); opacity: 1; } }

tailwind:
{/* keyframes twWave: translateY 55% -> -55% with opacity .4 -> 1 */}
<div className="inline-flex h-10 w-24 items-center justify-center gap-1.5">
  {[0, 100, 200, 300, 400].map((delay) => (
    <span
      key={delay}
      className="h-2.5 w-2.5 animate-[twWave_1.4s_ease-in-out_infinite] rounded-full bg-sky-500"
      style={{ animationDelay: delay + "ms" }}
    />
  ))}
</div>
